def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Last round is a simultaneous final action; defect is weakly dominant
    # once no future punishment is possible.
    if n == 99:
        return 'D'

    last_me, last_opp = history[-1]

    opp_c = 0
    opp_d = 0
    total_cd = 0
    for me, opp in history:
        if opp == 'C':
            opp_c += 1
        else:
            opp_d += 1
        if me == 'C' and opp == 'D':
            total_cd += 1

    opp_coop_rate = float(opp_c) / float(n)

    # Short recent window for soft forgiveness and exploitation confidence.
    recent_cd = 0
    recent_dc = 0
    recent_dd = 0
    w10 = 10 if n >= 10 else n
    s10 = n - w10
    for i in range(s10, n):
        me, opp = history[i]
        if me == 'C':
            if opp == 'D':
                recent_cd += 1
        else:
            if opp == 'C':
                recent_dc += 1
            else:
                recent_dd += 1

    # Longer recent window to avoid repeated failed peace offers.
    recent_cd16 = 0
    w16 = 16 if n >= 16 else n
    s16 = n - w16
    for i in range(s16, n):
        me, opp = history[i]
        if me == 'C' and opp == 'D':
            recent_cd16 += 1

    # Estimate whether the opponent tends to cooperate after we defected
    # (exploitable) or tend to defect after we defected (punishing).
    after_d_c = 0
    after_d_d = 0
    for i in range(n - 1):
        me = history[i][0]
        next_opp = history[i + 1][1]
        if me == 'D':
            if next_opp == 'C':
                after_d_c += 1
            else:
                after_d_d += 1

    # Streaks used for quick forgiveness and breaking mutual-defection cycles.
    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    my_c_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'C':
            my_c_streak += 1
        else:
            break

    mutual_d_streak = 0
    for i in range(n - 1, -1, -1):
        me, opp = history[i]
        if me == 'D' and opp == 'D':
            mutual_d_streak += 1
        else:
            break

    mutual_c_streak = 0
    for i in range(n - 1, -1, -1):
        me, opp = history[i]
        if me == 'C' and opp == 'C':
            mutual_c_streak += 1
        else:
            break

    # If opponent repeatedly gives us high-payoff unilateral cooperation, keep
    # exploiting. This handles unconditional-cooperator-like opponents and
    # independent defect patterns once they are observed.
    exploitable = False
    if n >= 3:
        if after_d_c >= 2 and after_d_c > after_d_d and opp_coop_rate > 0.5:
            exploitable = True

        if last_me == 'D' and last_opp == 'C':
            # Clean all-cooperator signal: no opponent defections yet.
            if opp_d == 0 and opp_coop_rate > 0.85:
                exploitable = True

            # Repeated tolerated defections with little evidence of punishment.
            if (opp_coop_rate > 0.6 and recent_cd <= 1 and
                    recent_dc >= 2 and recent_dd <= 1):
                exploitable = True

    if exploitable:
        return 'D'

    if last_opp == 'D':
        # If we just began a peace offer after a mutual-defection streak,
        # continue with one more C. TFT-like opponents then return C.
        if last_me == 'C' and my_c_streak == 1 and opp_d_streak >= 3:
            if n >= 2:
                p2 = history[-2]
                p1 = history[-1]
                if (p2[0] == 'D' and p2[1] == 'D' and
                        p1[0] == 'C' and p1[1] == 'D'):
                    return 'C'
            if total_cd <= 1 and opp_coop_rate > 0.85:
                return 'C'

        # Forgive a single isolated defection from a highly cooperative
        # opponent. This recovers quickly against one_D_TFT-like opponents.
        if (opp_d_streak == 1 and last_me == 'C' and recent_cd <= 1 and
                opp_coop_rate > 0.8 and opp_c >= 4):
            return 'C'

        # Break mutual punishment after a short streak if the opponent has
        # cooperated before and we have not recently failed too many offers.
        if mutual_d_streak >= 3 and opp_c >= 3 and recent_cd16 <= 2:
            return 'C'

        return 'D'

    # Opponent last cooperated.

    # Penultimate round: defect only when the opponent appears non-retaliatory.
    if n == 98:
        if opp_d == 0 and opp_coop_rate > 0.9 and mutual_c_streak >= 10:
            if rng.random() < 0.25:
                return 'D'
        if after_d_c > after_d_d and recent_cd == 0 and opp_coop_rate > 0.75:
            return 'D'
        return 'C'

    # Occasional controlled probe after stable cooperation.
    if (n >= 25 and mutual_c_streak >= 12 and
            opp_coop_rate > 0.7):
        if rng.random() < 0.07:
            return 'D'

    return 'C'
